def run_stage(label, script, args, defer=False):
    print(f"\n{'='*18} {label} {'='*18}", flush=True)
    env = os.environ.copy()
    if defer: env["UNIFIED_DEFER_DEPENDENCIES"] = "1"
    result = subprocess.run([sys.executable, str(script), *args], env=env)
    if result.returncode:
        raise RuntimeError(f"{label} stage failed; dependency linking was not run.")

class Jira:
    def __init__(self):
        base = os.getenv("JIRA_BASE_URL")
        email = os.getenv("JIRA_EMAIL")
        token = os.getenv("JIRA_API_TOKEN")
        missing = [n for n,v in (("JIRA_BASE_URL",base),("JIRA_EMAIL",email),("JIRA_API_TOKEN",token)) if not v]
        if missing: raise ValueError("Missing required environment variable(s): " + ", ".join(missing))
        self.base = base.rstrip("/")
        auth = base64.b64encode(f"{email}:{token}".encode()).decode()
        self.headers = {"Authorization": f"Basic {auth}", "Accept":"application/json", "Content-Type":"application/json"}
    def req(self, method, path, payload=None):
        body = json.dumps(payload).encode() if payload is not None else None
        request = urllib.request.Request(self.base+path, data=body, headers=self.headers, method=method)
        try:
            with urllib.request.urlopen(request, timeout=120) as response:
                raw=response.read(); return json.loads(raw) if raw else None
        except urllib.error.HTTPError as exc:
            detail=exc.read().decode(errors="replace")[:2000]
            raise RuntimeError(f"Jira API {method} {path} failed ({exc.code}): {detail}") from exc
    def issues(self, project):
        out=[]; token=None
        while True:
            payload={"jql":f'project = "{project}" AND issuetype in (Epic, Task, "Planned Task")',"fields":["summary","issuetype"],"maxResults":100}
            if token: payload["nextPageToken"]=token
            data=self.req("POST","/rest/api/3/search/jql",payload); out.extend(data.get("issues",[]))
            token=data.get("nextPageToken")
            if not token: return out
    def links(self,key):
        q=urllib.parse.quote(key,safe="")
        return self.req("GET",f"/rest/api/3/issue/{q}?fields=issuelinks")["fields"].get("issuelinks",[])

def workbook_dependencies(path: Path, sheet: str):
    wb=openpyxl.load_workbook(path,data_only=True)
    try:
        if sheet not in wb.sheetnames: raise ValueError(f"Sheet {sheet!r} not found.")
        ws=wb[sheet]; aliases={"id":{"id","no.","number"},"type":{"type","work type","issue type"},"name":{"name","summary","task name"},"dependencies":{"dependencies","dependency","depends on"}}
        header=None; cols={}
        for r in range(1,min(ws.max_row,40)+1):
            values={norm(ws.cell(r,c).value):c for c in range(1,ws.max_column+1)}
            found={k:next((values[a] for a in aa if a in values),None) for k,aa in aliases.items()}
            if all(found.values()): header=r; cols=found; break
        if not header: raise ValueError("Could not find ID, Type, Name, and Dependencies columns.")
        items={}; desired={}
        for r in range(header+1,ws.max_row+1):
            typ=clean(ws.cell(r,cols["type"]).value).title()
            if typ not in {"Epic","Task"}: continue
            source=sid(ws.cell(r,cols["id"]).value); name=clean(ws.cell(r,cols["name"]).value)
            if not source or not name: raise ValueError(f"Row {r}: {typ} ID and Name are required.")
            # All supplied scripts keep spreadsheet IDs out of Jira summaries.
            name=re.sub(r"^"+re.escape(source)+r"\s*[-:.)]?\s*","",name).strip()
            if source in items: raise ValueError(f"Duplicate spreadsheet ID {source!r}.")
            items[source]=(typ,name,r)
            raw=clean(ws.cell(r,cols["dependencies"]).value)
            deps=tuple(dict.fromkeys(sid(x) for x in DEP_SPLIT.split(raw) if sid(x)))
            desired[source]=deps
        for source,deps in desired.items():
            for dep in deps:
                if dep == source: raise ValueError(f"Row {items[source][2]}: {source} cannot depend on itself.")
                if dep not in items: raise ValueError(f"Row {items[source][2]}: dependency ID {dep!r} is not a Task or Epic in the workbook.")
        return items,desired
    finally: wb.close()

def sync_dependencies(path, sheet, project):
    items,desired=workbook_dependencies(path,sheet); jira=Jira()
    by_identity={}
    for issue in jira.issues(project):
        f=issue["fields"]; ident=(norm(f["issuetype"]["name"]),clean(f["summary"]).casefold())
        by_identity.setdefault(ident,[]).append(str(issue["key"]))
    keys={}
    for source,(typ,name,row) in items.items():
        jira_type = "planned task" if typ == "Task" else typ.lower()
        matches=by_identity.get((jira_type,name.casefold()),[])
        if not matches and typ == "Task":
            # Backward compatibility with Tasks created by older script versions.
            matches=by_identity.get(("task",name.casefold()),[])
        if len(matches)!=1:
            reason="not found" if not matches else "ambiguous: "+", ".join(matches)
            raise ValueError(f"Row {row}: Jira {typ} {name!r} is {reason}.")
        keys[source]=matches[0]
    print("\n================== DEPENDENCIES ==================",flush=True)
    for source,deps in desired.items():
        blocked=keys[source]; wanted={keys[d] for d in deps}; existing={}
        for link in jira.links(blocked):
            if norm(link.get("type",{}).get("name")) != "blocks": continue
            inward=link.get("inwardIssue")
            if inward and inward.get("key"): existing[str(inward["key"])]=str(link["id"])
        for blocker in sorted(set(existing)-wanted):
            jira.req("DELETE","/rest/api/3/issueLink/"+urllib.parse.quote(existing[blocker],safe=""))
            print(f"UNLINKED {blocked} is no longer blocked by {blocker}")
        for dep in deps:
            blocker=keys[dep]
            if blocker in existing: print(f"UNCHANGED {blocked} is blocked by {blocker}"); continue
            jira.req("POST","/rest/api/3/issueLink",{"type":{"name":"Blocks"},"inwardIssue":{"key":blocker},"outwardIssue":{"key":blocked}})
            print(f"LINKED   {blocker} blocks {blocked}")

def main():
    p=argparse.ArgumentParser(description="Run Releases, Components, Epics, Tasks, then synchronize all dependencies.")
    p.add_argument("workbook",type=Path); p.add_argument("--sheet",default="Plan")
    p.add_argument("--project-key",default=os.getenv("JIRA_PROJECT_KEY","TES")); p.add_argument("--apply",action="store_true")
    p.add_argument("--skip-status-transition",action="store_true")
    a=p.parse_args(); common=[str(a.workbook),"--sheet",a.sheet,"--project-key",a.project_key]
    if a.apply: common.append("--apply")
    status=["--skip-status-transition"] if a.skip_status_transition else []
    with tempfile.TemporaryDirectory(prefix="jira_unified_") as td:
        scripts=install_embedded(Path(td))
        # Keep existing releases synchronized when their calculated dates or
        # descriptions differ from the workbook.
        run_stage("RELEASES",scripts["releases"],common+["--update-existing"])
        run_stage("COMPONENTS",scripts["components"],common)
        run_stage("EPICS",scripts["epics"],common+status,defer=True)
        run_stage("TASKS",scripts["tasks"],common+status,defer=True)
    if a.apply: sync_dependencies(a.workbook,a.sheet,a.project_key)
    else: print("\nDry run complete. No Jira changes or dependency links were made.")
    return 0

if __name__ == "__main__":
    try: raise SystemExit(main())
    except (OSError,ValueError,RuntimeError,urllib.error.URLError) as exc:
        print(f"ERROR: {exc}",file=sys.stderr); raise SystemExit(1)